INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('28970227-6e6e-4347-8e4b-8ea01d654e41','9','geografie-fizica','published',2,141,1783500000000,1783500000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('28970227-6e6e-4347-8e4b-8ea01d654e41','ro','De ce rocile magmatice intruzive (plutonice) au cristale mari, iar cele efuzive (vulcanice) au cristale mici sau aspect sticlos?','["Pentru că rocile intruzive conțin mult mai mult siliciu decât cele efuzive.","Pentru că rocile efuzive sunt mult mai vechi decât cele intruzive.","Pentru că magma intruzivă se răcește lent în adânc, iar lava efuzivă se răcește repede la suprafață.","Pentru că rocile intruzive se formează din sedimente depuse în strate."]','Gândește-te cât timp au cristalele ca să crească. Răcirea lentă din adânc lasă cristalele să se dezvolte mari (granit), iar răcirea rapidă la suprafață le prinde mici sau chiar sticloase (bazalt, obsidian).');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('e183f1d5-587d-47e1-87ab-a4054635d0b4','9','geografie-fizica','published',0,142,1783500000000,1783500000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('e183f1d5-587d-47e1-87ab-a4054635d0b4','ro','Piatra ponce este singura rocă ce plutește pe apă. Care este explicația?','["Este plină de goluri lăsate de gazele din lavă, ceea ce o face foarte ușoară.","Este alcătuită din sare care se dizolvă și o ridică la suprafață.","Este o rocă metamorfică foarte dură și compactă.","S-a format prin depunerea lentă a nisipului pe fundul mării."]','Ce face un obiect să plutească? Densitatea mică. Gazele din lava răcită brusc au lăsat nenumărate goluri în piatra ponce, așa că densitatea ei scade sub cea a apei.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('1488e13b-0bb0-4524-9c5e-651872112f88','9','geografie-fizica','published',3,143,1783500000000,1783500000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('1488e13b-0bb0-4524-9c5e-651872112f88','ro','Într-o carieră observi o rocă dispusă în strate suprapuse, în care apar și fosile. Ce tip de rocă este, cel mai probabil?','["O rocă magmatică intruzivă.","O rocă magmatică efuzivă.","O rocă metamorfică.","O rocă sedimentară."]','Două indicii merg mână în mână: stratele și fosilele. Amândouă apar acolo unde materialul s-a depus în etape, la suprafață — semnătura clară a unei roci sedimentare.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('e2b74973-7fc9-4fa5-ac51-333f83a307fa','9','geografie-fizica','published',1,144,1783500000000,1783500000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('e2b74973-7fc9-4fa5-ac51-333f83a307fa','ro','Marmura, folosită pentru statui și placaje, se formează prin metamorfismul cărei roci?','["Al granitului.","Al calcarului.","Al gresiei.","Al argilei."]','Pornește de la o rocă sedimentară moale și vezi în ce se transformă sub presiune. Calcarul, supus temperaturii și presiunii mari, se recristalizează și devine marmură.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('fce1e1e1-b1f4-4d38-afe5-efedc5fbbe6c','9','geografie-fizica','published',2,145,1783500000000,1783500000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('fce1e1e1-b1f4-4d38-afe5-efedc5fbbe6c','ro','Gnaisul este o rocă metamorfică. Din ce rocă preexistentă se formează el?','["Din gresie.","Din calcar.","Din granit.","Din sare gemă."]','Caută o rocă dură, cu cristale mari, care sub presiune capătă un aspect vărgat. Granitul, transformat prin metamorfism, devine gnais, păstrând o parte din mineralele sale.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('7fe24f56-ed16-4721-86b5-6de7e7fdb923','9','geografie-fizica','published',0,146,1783500000000,1783500000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('7fe24f56-ed16-4721-86b5-6de7e7fdb923','ro','Cuarțitul, o rocă metamorfică foarte dură, provine din transformarea cărei roci sedimentare?','["A gresiei.","A calcarului.","A bazaltului.","A cărbunelui."]','Numele îți dă un indiciu: cuarț. Gresia, bogată în bobițe de cuarț (nisip consolidat), se transformă prin metamorfism în cuarțit, o rocă și mai dură.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('78b4dab1-85aa-4ac4-a566-5f285f196c27','9','geografie-fizica','published',1,147,1783500000000,1783500000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('78b4dab1-85aa-4ac4-a566-5f285f196c27','ro','De ce cărbunii și petrolul sunt încadrați la rocile sedimentare organogene?','["Pentru că se formează din răcirea lentă a lavei în adânc.","Pentru că provin din resturile unor viețuitoare (plante și organisme).","Pentru că se depun prin evaporarea apei sărate.","Pentru că se formează prin metamorfismul granitului."]','Rădăcina cuvântului organogen trimite la organisme vii. Cărbunii și petrolul s-au format din resturi de plante și viețuitoare acumulate și transformate în timp, deci sunt roci organogene.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('f3e9bb00-b57b-449a-bb99-ab3db86112a7','9','geografie-fizica','published',3,148,1783500000000,1783500000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('f3e9bb00-b57b-449a-bb99-ab3db86112a7','ro','Ce presupune, de fapt, metamorfismul unei roci?','["Topirea completă a rocii și transformarea ei în magmă.","Sfărâmarea rocii în fragmente transportate de ape.","Depunerea rocii în strate pe fundul mării.","Transformarea rocii în stare solidă, sub temperatură și presiune mari."]','Reține cuvintele-cheie: în stare solidă. Roca nu se topește (altfel ar deveni magmă), ci mineralele ei se rearanjează sub căldură și presiune, schimbându-i aspectul.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('ef648069-0739-4253-b192-1fc696493abb','9','geografie-fizica','published',0,149,1783500000000,1783500000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('ef648069-0739-4253-b192-1fc696493abb','ro','Obsidianul nu are cristale, ci un aspect de sticlă. Ce ne spune acest lucru despre formarea lui?','["Lava s-a răcit extrem de repede, fără să lase timp cristalelor să se formeze.","S-a format lent, în adâncimea scoarței.","Provine din depunerea cochiliilor pe fundul mării.","Este o rocă metamorfică transformată sub presiune."]','Fără cristale înseamnă fără timp de creștere. O răcire foarte bruscă a lavei la suprafață îngheață materialul ca pe o sticlă — așa apare obsidianul.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('5b8d4224-ce2d-4dcc-a43b-933574e831f1','9','geografie-fizica','published',2,150,1783500000000,1783500000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('5b8d4224-ce2d-4dcc-a43b-933574e831f1','ro','De ce calcarul poate fi socotit atât rocă sedimentară de precipitare chimică, cât și rocă organogenă?','["Pentru că este, în realitate, o rocă magmatică.","Pentru că se formează exclusiv prin răcirea magmei.","Pentru că se poate forma fie prin depunere chimică din apă, fie din cochilii și schelete de animale.","Pentru că provine din metamorfismul gresiei."]','O aceeași substanță poate ajunge rocă pe drumuri diferite. Carbonatul de calciu se poate depune chimic din apă, dar și din cochiliile animalelor — de aceea calcarul are două origini.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('2bef3dcd-44d4-431b-a92c-5fa1307ddf66','9','geografie-fizica','published',3,151,1783500000000,1783500000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('2bef3dcd-44d4-431b-a92c-5fa1307ddf66','ro','Care este ordinea corectă a etapelor prin care se formează o rocă sedimentară detritică?','["Topire, apoi răcire, apoi cristalizare.","Metamorfism, apoi topire, apoi depunere.","Depunere, apoi topire, apoi eroziune.","Dezagregare și eroziune, apoi transport, apoi depunere, apoi consolidare."]','Urmărește o bucată de rocă de la munte până în albia unui râu. Ea se sfărâmă, este cărată de ape, se depune și, în timp, se întărește — exact drumul unei roci detritice.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('0cf74492-0e39-46c8-afbe-7f2c7f2f58ea','9','geografie-fizica','published',1,152,1783500000000,1783500000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('0cf74492-0e39-46c8-afbe-7f2c7f2f58ea','ro','Ce au în comun granitul și bazaltul, deși arată diferit?','["Ambele sunt roci sedimentare depuse în strate.","Ambele sunt roci magmatice, unul intruziv, celălalt efuziv.","Ambele sunt roci metamorfice formate sub presiune.","Ambele se formează din cochilii de animale marine."]','Ignoră mărimea cristalelor și întreabă-te din ce s-au format. Amândouă provin din solidificarea magmei, deci sunt magmatice; granitul în adânc (intruziv), bazaltul la suprafață (efuziv).');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('a1180144-54f7-48c7-b81b-2c0e4279aa6d','9','geografie-fizica','published',0,153,1783500000000,1783500000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('a1180144-54f7-48c7-b81b-2c0e4279aa6d','ro','O rocă are cristale mari, vizibile cu ochiul liber, și s-a format în adâncul scoarței. Ce este ea, cel mai probabil?','["O rocă magmatică intruzivă, precum granitul.","O rocă sedimentară detritică, precum gresia.","O rocă organogenă, precum cărbunele.","O piatră ponce vulcanică."]','Leagă locul de formare de mărimea cristalelor. Adâncul înseamnă răcire lentă, deci cristale mari — semnul unei roci magmatice intruzive, cum este granitul.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9522194a-5f63-45cf-8c7d-5f338c8b564d','9','geografie-fizica','published',2,154,1783500000000,1783500000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9522194a-5f63-45cf-8c7d-5f338c8b564d','ro','Prin ce se deosebește o rocă de un mineral?','["Roca este întotdeauna un singur cristal perfect.","Mineralul este un amestec de mai multe roci.","Roca este un agregat natural de unul sau mai multe minerale.","Nu există nicio deosebire între ele."]','Gândește la relația parte-întreg. Mineralul este cărămida, iar roca este zidul: un agregat natural alcătuit din unul sau mai multe minerale legate între ele.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('fb6363ad-997c-44b2-b2e2-beab5d3eda6d','9','geografie-fizica','published',1,155,1783500000000,1783500000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('fb6363ad-997c-44b2-b2e2-beab5d3eda6d','ro','De ce sarea gemă și gipsul sunt încadrate la rocile sedimentare de precipitare chimică?','["Pentru că se formează din răcirea lentă a lavei.","Pentru că se depun din substanțe dizolvate în apă, atunci când aceasta se evaporă.","Pentru că provin din cochilii și schelete de animale.","Pentru că iau naștere prin metamorfismul calcarului."]','Imaginează-ți o baltă sărată care seacă la soare. Când apa se evaporă, substanțele dizolvate rămân și se depun (precipită) — așa se formează sarea gemă și gipsul.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('64c91061-be1d-457d-a936-989dab93f73a','9','geografie-fizica','published',3,156,1783500000000,1783500000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('64c91061-be1d-457d-a936-989dab93f73a','ro','Ardezia (șisturile argiloase) se formează prin metamorfismul cărei roci?','["Al calcarului.","Al granitului.","Al gresiei.","Al argilei."]','Pornește de la o rocă moale, cu particule fine, și vezi ce devine sub presiune. Argila, compactată și transformată, dă ardezia, o rocă ce se desface ușor în plăci subțiri.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('246e6d7d-6d9d-40f7-a949-822b20d89d89','9','geografie-fizica','published',0,157,1783500000000,1783500000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('246e6d7d-6d9d-40f7-a949-822b20d89d89','ro','În circuitul rocilor, ce se poate întâmpla cu o rocă sedimentară îngropată la mare adâncime, sub presiune și temperatură ridicate?','["Se transformă într-o rocă metamorfică.","Devine pe loc piatră ponce.","Se preface într-un singur mineral pur.","Urcă la suprafață fără nicio schimbare."]','Adâncime mare înseamnă presiune și căldură mari, dar nu neapărat topire. În aceste condiții roca sedimentară se transformă, în stare solidă, într-o rocă metamorfică.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('e5b251a4-e713-4346-aa69-97a46cb60cec','9','geografie-fizica','published',2,158,1783500000000,1783500000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('e5b251a4-e713-4346-aa69-97a46cb60cec','ro','Ce se întâmplă cu o rocă dacă temperatura crește atât de mult încât aceasta se topește?','["Devine imediat o rocă sedimentară în strate.","Rămâne complet neschimbată.","Redevine magmă, din care, prin răcire, se va forma o nouă rocă magmatică.","Se transformă într-o fosilă."]','Urmează firul circuitului rocilor până la capăt. Topirea desface roca înapoi în magmă; când aceasta se răcește, ciclul reîncepe cu o rocă magmatică.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('ec6e793f-e2c1-49f8-aeb4-6140840fdc6c','9','geografie-fizica','published',1,159,1783500000000,1783500000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('ec6e793f-e2c1-49f8-aeb4-6140840fdc6c','ro','De ce cărbunii și petrolul au o importanță deosebită pentru oameni?','["Pentru că din ele se fabrică marmura pentru statui.","Pentru că sunt combustibili care ne furnizează energie.","Pentru că din ele se extrage sarea de bucătărie.","Pentru că sunt cele mai dure materiale de construcție."]','Întreabă-te la ce le folosim zilnic. Cărbunii și petrolul ard și eliberează energie, deci principala lor valoare este aceea de combustibili.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('a6bb8018-9868-4825-bd12-99d6b263eee5','9','geografie-fizica','published',3,160,1783500000000,1783500000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('a6bb8018-9868-4825-bd12-99d6b263eee5','ro','Gresia se formează prin consolidarea nisipului. La ce tip de roci sedimentare o încadrăm?','["La cele de precipitare chimică.","La cele organogene.","La cele magmatice.","La cele detritice (clastice)."]','Nisipul este format din fragmente (detritus) provenite din alte roci. O rocă alcătuită din astfel de fragmente cimentate este detritică (clastică) — cazul gresiei.');
